+import { useEffect, useRef } from "react";
+
+export default function HeroSection() {
+  const sceneRef = useRef(null);
+  const frontTagRef = useRef(null);
+  const backTagRef = useRef(null);
+
+  useEffect(() => {
+    const handleMove = (e) => {
+      const x = e.clientX / window.innerWidth - 0.5;
+      const y = e.clientY / window.innerHeight - 0.5;
+
+      if (frontTagRef.current) {
+        frontTagRef.current.style.transform = `
+          translate(${x * 8}px, ${y * 6}px)
+          rotate(${x * 1.5}deg)
+        `;
+      }
+
+      if (backTagRef.current) {
+        backTagRef.current.style.transform = `
+          translate(${x * 5}px, ${y * 4}px)
+          rotate(${x * 1.1}deg)
+        `;
+      }
+
+      if (sceneRef.current) {
+        sceneRef.current.style.transform = "translate(-50%,-46%)";
+      }
+    };
+
+    window.addEventListener("mousemove", handleMove);
+    return () => window.removeEventListener("mousemove", handleMove);
+  }, []);
+
+  return (
+    <section className="hero">
+      <div className="scene" ref={sceneRef}>
+
+        {/* strings */}
+        <div className="string back"></div>
+        <div className="string front"></div>
+
+        {/* BACK CARD */}
+        <div className="tag-back float" ref={backTagRef}>
+          <div className="paper-noise"></div>
+          <div className="paper-smudge"></div>
+          <div className="barcode"></div>
+          <div className="sweden">made in sweden</div>
+          <div className="rebranding">ongoing rebranding</div>
+        </div>
+
+        {/* FRONT CARD */}
+        <div className="tag-front float" ref={frontTagRef}>
+          <div className="paper-noise"></div>
+          <div className="paper-smudge"></div>
+
+          {/* 👇 المحتوى الجديد داخل البطاقة */}
+          <div className="profile-content">
+
+            {/* صورة */}
+            <div className="profile-img">
+              <img src="c." alt="Ibrahim" />
+            </div>
+
+            {/* الاسم */}
+            <h2 className="name">Ibrahim Talb</h2>
+
+            {/* الوظيفة */}
+            <p className="role">Full Stack Developer</p>
+
+            {/* خط فاصل */}
+            <div className="divider"></div>
+
+            {/* الإيميل */}
+            <p className="email">ibrahim@email.com</p>
+
+          </div>
+        </div>
+
+        {/* hole */}
+        <div className="hole front"></div>
+
+      </div>
+    </section>
+  );
