+import { useEffect, useRef } from "react";
+import {
+  motion,
+  useMotionValue,
+  useSpring,
+  useTransform,
+} from "framer-motion";
+
+export default function HeroSection() {
+  const backTagRef = useRef(null);
+
+  // drag source
+  const dragY = useMotionValue(0);
+  const dragX = useMotionValue(0);
+
+  // spring return
+  const springY = useSpring(dragY, {
+    stiffness: 180,
+    damping: 12,
+    mass: 0.7,
+  });
+
+  const springX = useSpring(dragX, {
+    stiffness: 180,
+    damping: 14,
+    mass: 0.7,
+  });
+
+  // scene motion
+  const sceneY = useTransform(springY, [0, 180], [0, 150]);
+  const sceneX = useTransform(springX, [-40, 40], [-12, 12]);
+
+  // front card rotation
+  const frontRotate = useTransform(
+    [springX, springY],
+    ([x, y]) => x * 0.06 + y * 0.018
+  );
+
+  // back card rotation
+  const backRotate = useTransform(
+    [springX, springY],
+    ([x, y]) => x * 0.035 + y * 0.01
+  );
+
+  // strings stretch
+  const frontStringHeight = useTransform(springY, [0, 180], [220, 365]);
+  const backStringHeight = useTransform(springY, [0, 180], [212, 335]);
+
+  // subtle scale stretch on pull
+  const frontScaleY = useTransform(springY, [0, 180], [1, 1.025]);
+  const backScaleY = useTransform(springY, [0, 180], [1, 1.015]);
+
+  useEffect(() => {
+    const handleMove = (e) => {
+      const x = e.clientX / window.innerWidth - 0.5;
+      const y = e.clientY / window.innerHeight - 0.5;
+
+      if (backTagRef.current) {
+        const subtleX = x * 5;
