+import { motion, useMotionValue, useTransform } from "framer-motion";
+
+export default function HeroSection() {
+  const sceneRef = useRef(null);
+  const backTagRef = useRef(null);
+
+  const dragY = useMotionValue(0);
+
+  const frontStretch = useTransform(dragY, [0, 180], [1, 1.08]);
+  const backStretch = useTransform(dragY, [0, 180], [1, 1.035]);
+
+  const frontTilt = useTransform(dragY, [0, 180], [0, 2.4]);
+  const backTilt = useTransform(dragY, [0, 180], [0, 1.2]);
+
+  const frontMicroY = useTransform(dragY, [0, 180], [0, 12]);
+  const backMicroY = useTransform(dragY, [0, 180], [0, 8]);
+
+  const frontStringHeight = useTransform(dragY, [0, 180], [220, 350]);
+  const backStringHeight = useTransform(dragY, [0, 180], [212, 320]);
+
+  useEffect(() => {
+    const handleMove = (e) => {
+      const x = e.clientX / window.innerWidth - 0.5;
+      const y = e.clientY / window.innerHeight - 0.5;
+
+      if (backTagRef.current) {
+        backTagRef.current.style.transform = `
+          translate(${x * 4}px, ${y * 2}px)
+          rotate(${x * 1}deg)
+        `;
