import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import useMouseTilt from "../hooks/useMouseTilt";

export default function HeroSection() {
  const { transform, handleMove, reset } = useMouseTilt(2);

  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const smoothX = useSpring(mouseX, { stiffness: 60, damping: 20 });
  const smoothY = useSpring(mouseY, { stiffness: 60, damping: 20 });

  const glowX = useTransform(smoothX, [-200, 200], ["35%", "65%"]);
  const glowY = useTransform(smoothY, [-200, 200], ["30%", "70%"]);

  const onMove = (e) => {
    handleMove(e);
    const rect = e.currentTarget.getBoundingClientRect();
    mouseX.set(e.clientX - (rect.left + rect.width / 2));
    mouseY.set(e.clientY - (rect.top + rect.height / 2));
  };

  const onLeave = () => {
    reset();
    mouseX.set(0);
    mouseY.set(0);
  };

  return (
    <section
      id="hero"
      className="relative flex min-h-screen items-center justify-center overflow-hidden bg-lightBg px-6 pt-28"
    >
      <div className="pointer-events-none absolute inset-0 bg-hero-grid" />
      <div className="noise animate-grain opacity-20" />

      <motion.div
        initial={{ opacity: 0, y: 32, scale: 0.98 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        transition={{ duration: 1.1, ease: [0.22, 1, 0.36, 1] }}
        className="relative flex flex-col items-center"
      >
        <div className="mb-[-4px] h-20 w-px bg-gradient-to-b from-transparent via-stone-500/70 to-stone-300" />

        <motion.div
          onMouseMove={onMove}
          onMouseLeave={onLeave}
          style={{ transformStyle: "preserve-3d", transform }}
          className="hero-card-shadow group relative flex h-[430px] w-[260px] select-none flex-col items-center justify-center overflow-hidden rounded-[18px] border border-black/[0.04] bg-cardWhite sm:h-[470px] sm:w-[290px]"
        >
          <motion.div
            style={{
              background: useTransform(
                [glowX, glowY],
                ([x, y]) =>
                  `radial-gradient(circle at ${x} ${y}, rgba(255,255,255,0.95), rgba(255,255,255,0.0) 42%)`
              ),
            }}
            className="pointer-events-none absolute inset-0 opacity-80"
          />

          <div className="absolute top-6 h-4 w-4 rounded-full border border-black/10 bg-[#ececec] shadow-inner" />
          <div className="noise animate-grain opacity-20 transition duration-500 group-hover:opacity-35" />

          <div className="relative z-10 px-6 text-center">
            <motion.p
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.35, duration: 0.7 }}
              className="text-[13px] font-medium tracking-[0.28em] text-textPrimary uppercase"
            >
              Ibrahim
            </motion.p>

            <motion.p
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.48, duration: 0.7 }}
              className="mt-3 text-[11px] tracking-[0.2em] text-textSecondary uppercase"
            >
              Full Stack Developer
            </motion.p>
          </div>

          <div className="pointer-events-none absolute inset-x-8 bottom-6 h-px bg-gradient-to-r from-transparent via-black/10 to-transparent" />
        </motion.div>

        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.85, duration: 0.8 }}
          className="mt-10 max-w-md text-center text-sm leading-7 text-textSecondary"
        >
          Quiet design, strong systems, and polished digital experiences.
        </motion.p>
      </motion.div>
    </section>
  );
}
